  ts INTEGER NOT NULL,
  PRIMARY KEY (news_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_news_reactions_news ON news_reactions (news_id);
CREATE TABLE IF NOT EXISTS news_versions (
