@tailwind base;
@tailwind components;
@tailwind utilities;

/* "Bento 2.0": soft washes on the page, white 26px tiles, gradient accents derived from --brand.
   Palette as space-separated RGB so Tailwind can apply opacity (bg-brand/20).
   Light is the default; dark applies with the system setting unless a theme is chosen explicitly.
   Contrast (WCAG 2.1, checked for both themes): text tokens (mute, link, ok, warn, bad on page/card/soft and on their pill
   backgrounds) >= 4.5:1; white on brand / brand-2 / badsolid >= 4.5:1; --field (input borders) >= 3:1 on card, soft and page.
   --line is decorative only (tile borders, dividers).
   --brand-2 (the darker end of every brand gradient) is set by useBrand() from the chosen brand colour. */
:root {
  --page: 243 244 248;
  --card: 255 255 255;
  --raised: 255 255 255;
  --ink: 18 20 26;
  --mute: 92 99 114;
  --line: 231 233 240;
  --field: 122 129 143;
  --soft: 236 238 246;
  --brand: 79 70 229;
  --brand-hover: 67 56 202;
  --brand-2: 61 51 190;
  --link: 79 70 229;
  --ok: 18 120 66;
  --okbg: 220 247 232;
  --warn: 146 94 0;
  --warnbg: 255 241 205;
  --bad: 185 40 40;
  --badbg: 254 226 226;
  --badsolid: 185 40 40;
  --oksolid: 21 128 61;
  --seg-on: 255 255 255;
  --tile-border: rgb(231 233 240);
  --glass: rgb(255 255 255 / 0.74);
  --glass-border: rgb(255 255 255 / 0.9);
  --glass-shadow: 0 8px 30px rgba(40, 50, 110, 0.08);
  /* shadow scale: 1 = small controls and chips, 2 = cards and tiles at rest, 3 = floating (menus, dialogs, hovered cards) */
  --shadow-1: 0 1px 2px rgba(20, 24, 40, 0.08), 0 2px 8px rgba(40, 50, 110, 0.06);
  --shadow-2: 0 1px 2px rgba(20, 24, 40, 0.04), 0 12px 30px rgba(40, 50, 110, 0.06);
  --shadow-3: 0 1px 2px rgba(20, 24, 40, 0.06), 0 18px 38px rgba(40, 50, 110, 0.13);
  --horizon-a: rgb(var(--brand) / 0.14);
  --horizon-b: rgb(236 72 153 / 0.22);
  --wash-a: rgb(var(--brand) / 0.15);
  --wash-b: rgb(70 190 235 / 0.14);
  color-scheme: light;
}
/* radius scale (sm / md / lg / xl / pill) and the old shadow names as aliases of the shadow scale */
:root {
  --r-sm: 8px;
  --r-md: 12px;
  --r-lg: 16px;
  --r-xl: 26px;
  --r-pill: 9999px;
  --shadow-pop: var(--shadow-1);
  --shadow-soft: var(--shadow-2);
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    --page: 9 10 14;
    --card: 18 20 27;
    --raised: 27 30 40;
    --ink: 226 228 236;
    --mute: 148 154 170;
    --line: 38 41 53;
    --field: 112 118 136;
    --soft: 30 33 44;
    --brand: 88 91 235;
    --brand-hover: 76 79 214;
    --brand-2: 66 58 196;
    --link: 165 170 255;
    --ok: 74 222 128;
    --okbg: 18 52 36;
    --warn: 251 191 36;
    --warnbg: 54 43 14;
    --bad: 248 113 113;
    --badbg: 58 25 30;
    --badsolid: 214 48 48;
    --seg-on: 44 48 64;
    --tile-border: rgb(255 255 255 / 0.07);
    --glass: rgb(20 22 30 / 0.72);
    --glass-border: rgb(255 255 255 / 0.08);
    --glass-shadow: 0 10px 34px rgba(0, 0, 0, 0.5);
    --shadow-1: 0 1px 0 rgb(255 255 255 / 0.05) inset, 0 2px 8px rgba(0, 0, 0, 0.5);
    --shadow-2: 0 1px 0 rgb(255 255 255 / 0.05) inset, 0 16px 34px -18px rgba(0, 0, 0, 0.8);
    --shadow-3: 0 1px 0 rgb(255 255 255 / 0.07) inset, 0 24px 48px -16px rgba(0, 0, 0, 0.9);
    --horizon-a: rgb(var(--brand) / 0.2);
    --horizon-b: rgb(236 72 153 / 0.2);
    --wash-a: rgb(var(--brand) / 0.2);
    --wash-b: rgb(40 170 210 / 0.09);
    color-scheme: dark;
  }
}
:root[data-theme='dark'] {
  --page: 9 10 14;
  --card: 18 20 27;
  --raised: 27 30 40;
  --ink: 226 228 236;
  --mute: 148 154 170;
  --line: 38 41 53;
  --field: 112 118 136;
  --soft: 30 33 44;
  --brand: 88 91 235;
  --brand-hover: 76 79 214;
  --brand-2: 66 58 196;
  --link: 165 170 255;
  --ok: 74 222 128;
  --okbg: 18 52 36;
  --warn: 251 191 36;
  --warnbg: 54 43 14;
  --bad: 248 113 113;
  --badbg: 58 25 30;
  --badsolid: 214 48 48;
  --seg-on: 44 48 64;
  --tile-border: rgb(255 255 255 / 0.07);
  --glass: rgb(20 22 30 / 0.72);
  --glass-border: rgb(255 255 255 / 0.08);
  --glass-shadow: 0 10px 34px rgba(0, 0, 0, 0.5);
  --shadow-1: 0 1px 0 rgb(255 255 255 / 0.05) inset, 0 2px 8px rgba(0, 0, 0, 0.5);
  --shadow-2: 0 1px 0 rgb(255 255 255 / 0.05) inset, 0 16px 34px -18px rgba(0, 0, 0, 0.8);
  --shadow-3: 0 1px 0 rgb(255 255 255 / 0.07) inset, 0 24px 48px -16px rgba(0, 0, 0, 0.9);
  --horizon-a: rgb(var(--brand) / 0.2);
  --horizon-b: rgb(236 72 153 / 0.2);
  --wash-a: rgb(var(--brand) / 0.2);
  --wash-b: rgb(40 170 210 / 0.09);
  color-scheme: dark;
}

@layer base {
  html, body, #root { min-height: 100%; }
  /* the body carries the background glow: it must reach the bottom of the window on short pages too (html has no
     fixed height, so min-height: 100% alone resolved to the content height and the glow ended in a hard line) */
  body { min-height: 100vh; min-height: 100dvh; }
  body {
    @apply bg-page text-ink font-sans text-[15px] antialiased;
    -webkit-text-size-adjust: 100%;
  }
  /* page background "Горизонт": a glow along the lower edge of the first screen (brand + pink) fading both ways.
     Painted on the body itself and static: no fixed layer, no animation (a fixed full-screen layer once showed as a black tile) */
  body {
    background-image:
      radial-gradient(90% 30% at 50% 77%, var(--horizon-b), transparent 72%),
      linear-gradient(180deg, transparent 32%, var(--horizon-a) 77%, transparent 100%);
    background-size: 100% 130vh;
    background-repeat: no-repeat;
    background-position: top;
  }

  ::selection { @apply bg-brand/30; }
  :focus-visible { @apply outline-none ring-2 ring-link; }
  /* long words (usernames, addresses) must not stretch the layout. break-word, not anywhere: anywhere also lowers the
     minimum width, and a heading in a flex row then shrank to a couple of letters per line («Показате / ли») */
  h1, h2, h3 { overflow-wrap: break-word; }
}

@layer components {
  /* buttons (.btn, .btn-soft, .btn-icon ...): styles/buttons.css */
  .input { @apply w-full rounded-ui-lg border-2 border-field bg-card px-3.5 py-2 font-semibold text-ink placeholder:font-normal placeholder:text-mute focus:border-link focus:outline-none disabled:opacity-60 max-sm:min-h-[44px] max-sm:text-[16px]; }
  .label { @apply mb-1.5 block text-sm font-extrabold text-mute; }
  /* the tile: white card, 26px radius, layered soft shadow */
  .panel { @apply rounded-ui-xl bg-card; border: 1px solid var(--tile-border); box-shadow: var(--shadow-2); }
  .tile { @apply rounded-ui-xl bg-card; border: 1px solid var(--tile-border); box-shadow: var(--shadow-2); }
  /* floating surfaces (dialogs, menus, popovers): one step above the card in the dark theme, identical in the light one */
  .panel-raised { background-color: rgb(var(--raised)); box-shadow: var(--shadow-3); }
  .pill { @apply inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-[13px] font-extrabold; }
  .pill::before { content: ''; @apply h-1.5 w-1.5 rounded-full bg-current; }
  .pill-ok { @apply bg-okbg text-ok; }
  .pill-warn { @apply bg-warnbg text-warn; }
  .pill-bad { @apply bg-badbg text-bad; }
  .pill-mute { @apply bg-soft text-mute; }

  /* segmented control: soft capsule with a white (lifted) active pill. Works for links and buttons. */
  .seg { @apply relative inline-flex gap-0.5 rounded-full bg-soft p-[3px]; }
  .seg-item {
    @apply relative inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-full px-4 py-1.5 text-sm font-extrabold text-mute transition hover:text-ink max-sm:min-h-[44px];
  }
  .seg-item[aria-pressed='true'], .seg-item[aria-current='page'], .seg-item.on {
    color: rgb(var(--ink));
    background: rgb(var(--seg-on));
    box-shadow: var(--shadow-1);
  }

  /* the sticky glass header and the floating bottom bar */
  .glass {
    background: var(--glass);
    border: 1px solid var(--glass-border);
    box-shadow: var(--glass-shadow);
    -webkit-backdrop-filter: blur(18px) saturate(1.4);
    backdrop-filter: blur(18px) saturate(1.4);
  }

  /* tiles with a game gradient (--c1 -> --c2, set inline); white text on top, gradients are kept dark enough */
  .cover-grad { background: linear-gradient(135deg, var(--c1), var(--c2)); color: #fff; }
  .stat-k { @apply text-[13px] font-extrabold text-mute; }
  .stat-v { @apply text-[34px] font-extrabold leading-[1.05] tabular-nums sm:text-[40px]; letter-spacing: -0.03em; }
  .stat-v small { @apply text-lg font-bold text-mute; letter-spacing: 0; }
  .stat-s { @apply text-[13px] font-bold text-mute; }
  /* translucent chip on a gradient tile */
  .chip-on-grad { @apply inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-[13px] font-extrabold text-white; background: rgba(255, 255, 255, 0.22); }
  .tile-hover { transition: transform .18s ease, box-shadow .18s ease; }
  .tile-hover:hover { transform: translateY(-2px); box-shadow: var(--shadow-3); }
  @media (prefers-reduced-motion: reduce) { .tile-hover:hover { transform: none; } }
}

@keyframes pop { from { opacity: 0; transform: translateY(8px) scale(.98); } to { opacity: 1; transform: none; } }
.pop { animation: pop .25s ease-out both; }
@keyframes shimmer { 0%, 100% { opacity: .55; } 50% { opacity: 1; } }
.skeleton { animation: shimmer 1.4s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .pop, .skeleton { animation: none; } }

/* a gently pulsing ring on the ONLINE pill */
@keyframes live-ring {
  0% { box-shadow: 0 0 0 0 rgb(var(--ok) / 0.45); }
  70% { box-shadow: 0 0 0 7px rgb(var(--ok) / 0); }
  100% { box-shadow: 0 0 0 0 rgb(var(--ok) / 0); }
}
.pill.live::before { animation: live-ring 2.2s ease-out infinite; }
@media (prefers-reduced-motion: reduce) { .pill.live::before { animation: none; } }

.input[aria-invalid='true'] { border-color: rgb(var(--bad)); }

/* ---------- sign-in screens ---------- */
:root { --auth-glow: 0.14; }
:root[data-theme='dark'] { --auth-glow: 0.28; }
@media (prefers-color-scheme: dark) { :root:not([data-theme='light']) { --auth-glow: 0.28; } }

/* soft brand-coloured light behind the card */
.auth-glow {
  position: absolute; inset: 0; pointer-events: none;
  background:
    radial-gradient(42rem 32rem at 50% 42%, rgb(var(--brand) / var(--auth-glow)), transparent 70%),
    radial-gradient(26rem 22rem at 12% 8%, rgb(var(--brand) / calc(var(--auth-glow) * 0.55)), transparent 70%),
    radial-gradient(28rem 24rem at 92% 96%, rgb(var(--brand) / calc(var(--auth-glow) * 0.55)), transparent 70%);
  animation: auth-glow 9s ease-in-out infinite alternate;
}
@keyframes auth-glow { from { opacity: .75; } to { opacity: 1; } }

.auth-float {
  position: absolute; left: var(--x); top: var(--y); width: var(--s); height: var(--s);
  color: rgb(var(--brand)); opacity: .12; pointer-events: none;
  transform: rotate(var(--r));
  animation: auth-float var(--d) ease-in-out infinite alternate;
}
:root[data-theme='dark'] .auth-float { opacity: .16; }
@media (prefers-color-scheme: dark) { :root:not([data-theme='light']) .auth-float { opacity: .16; } }
@keyframes auth-float {
  from { transform: translate3d(0, 0, 0) rotate(var(--r)); }
  to { transform: translate3d(16px, -30px, 0) rotate(calc(var(--r) + 14deg)); }
}

.auth-card {
  border-color: rgb(var(--brand) / calc(var(--auth-glow) * 1.1));
  box-shadow: 0 28px 60px -28px rgb(var(--brand) / calc(var(--auth-glow) * 2.2)), 0 2px 8px rgb(0 0 0 / 0.06);
  animation: auth-card-in .45s cubic-bezier(.2, .8, .2, 1) both;
}
:root[data-theme='dark'] .auth-card { box-shadow: 0 28px 70px -24px rgb(var(--brand) / 0.5), 0 2px 10px rgb(0 0 0 / 0.5); }
@media (prefers-color-scheme: dark) { :root:not([data-theme='light']) .auth-card { box-shadow: 0 28px 70px -24px rgb(var(--brand) / 0.5), 0 2px 10px rgb(0 0 0 / 0.5); } }
@keyframes auth-card-in { from { opacity: 0; transform: translateY(18px) scale(.97); } to { opacity: 1; transform: none; } }

.auth-swap { animation: auth-swap .3s ease-out both; }
@keyframes auth-swap { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

.shake { animation: auth-shake .42s cubic-bezier(.36, .07, .19, .97) both; }
@keyframes auth-shake {
  10%, 90% { transform: translateX(-1px); }
  20%, 80% { transform: translateX(3px); }
  30%, 50%, 70% { transform: translateX(-6px); }
  40%, 60% { transform: translateX(6px); }
}

/* ---------- shared helpers ---------- */
/* "skip to content" link: visible only while focused */
.skip-link {
  position: fixed; left: 1rem; top: 0.75rem; z-index: 100;
  transform: translateY(-200%);
  border-radius: 9999px; padding: 0.6rem 1.1rem; font-weight: 800;
  background: rgb(var(--brand)); color: #fff; box-shadow: 0 6px 20px rgb(0 0 0 / 0.25);
}
.skip-link:focus { transform: none; }
/* <main> gets focus programmatically on every route change: no ring around the whole page */
main:focus,
main:focus-visible { outline: none; box-shadow: none; --tw-ring-shadow: 0 0 #0000; }

/* a value that just changed: short glow */
@keyframes num-bump {
  0% { text-shadow: 0 0 0 rgb(var(--ok) / 0); }
  30% { text-shadow: 0 0 16px rgb(var(--ok) / 0.55); color: rgb(var(--ok)); }
  100% { text-shadow: 0 0 0 rgb(var(--ok) / 0); }
}
.num-bump { animation: num-bump .9s ease-out; }

/* touch devices: bigger hit areas for small controls without changing the desktop look */
@media (max-width: 639px) {
  input[type='checkbox']:not(.switch), input[type='radio'] { width: 1.25rem !important; height: 1.25rem !important; }
  label:has(> input[type='checkbox']), label:has(> input[type='radio']) { min-height: 44px; }
  /* text-style buttons ("Обновить список", "Показать правила") */
  button.text-link { min-height: 44px; display: inline-flex; align-items: center; }
  /* section navigation of the admin area and of the settings (their pages are not ours: target them by label) */
  nav[aria-label='Разделы админки'] a, nav[aria-label='Разделы настроек'] a { min-height: 44px; display: flex; align-items: center; justify-content: center; }
  nav[aria-label='Разделы админки'] { scroll-snap-type: x proximity; }
  nav[aria-label='Разделы админки'] a { scroll-snap-align: center; justify-content: flex-start; }
  select, textarea, input:not([type='checkbox']):not([type='radio']):not([type='range']):not([type='file']):not([type='color']) { font-size: 16px; }
}

/* ---------- reduced motion: no animations, no transitions ---------- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    animation-delay: 0s !important;
    transition-duration: 0.01ms !important;
    transition-delay: 0s !important;
    scroll-behavior: auto !important;
  }
  .auth-glow, .auth-float, .skeleton, .pill.live::before { animation: none !important; }
  /* a spinner must still say "busy": keep a slow rotation */
  .animate-spin { animation: spin 2s linear infinite !important; }
  .active\:scale-\[\.98\]:active, .hover\:-translate-y-0\.5:hover, .hover\:scale-110:hover { transform: none !important; }
}

/* decorative tiles next to the sign-in card */
.showcase-tile { animation: showcase-in .6s cubic-bezier(.2, .8, .2, 1) both; }
@keyframes showcase-in { from { opacity: 0; transform: translateY(20px) scale(.96) rotate(0deg); } }
@media (prefers-reduced-motion: reduce) { .showcase-tile { animation: none; } }

/* ---------- motion: staggered tiles, chart reveal, meters, live dot, skeleton sweep ---------- */
.tile-in { animation: tile-in .55s cubic-bezier(.2, .8, .2, 1) both; animation-delay: calc(var(--i, 0) * 55ms); }
@keyframes tile-in { from { opacity: 0; transform: translateY(18px) scale(.97); } to { opacity: 1; transform: none; } }

.chart-reveal { animation: chart-reveal 1.1s cubic-bezier(.3, .7, .2, 1) .25s both; }
@keyframes chart-reveal { from { clip-path: inset(-20% 100% -20% 0); } to { clip-path: inset(-20% -3% -20% 0); } }

.meter { height: 6px; border-radius: 9999px; background: rgb(var(--soft)); overflow: hidden; }
.meter > i { display: block; height: 100%; border-radius: 9999px; background: linear-gradient(90deg, rgb(var(--brand)), rgb(var(--brand-2, var(--brand)))); transition: width 1.1s cubic-bezier(.2, .8, .2, 1); animation: meter-in 1.1s cubic-bezier(.2, .8, .2, 1) both; }
@keyframes meter-in { from { width: 0; } }

.live-dot { position: relative; width: 8px; height: 8px; border-radius: 9999px; background: rgb(var(--ok)); }
.live-dot::after { content: ''; position: absolute; inset: 0; border-radius: inherit; background: rgb(var(--ok)); animation: live-ping 1.8s cubic-bezier(0, 0, .2, 1) infinite; }
@keyframes live-ping { 75%, 100% { transform: scale(2.6); opacity: 0; } }

.offline-cover { opacity: .78; }

.skeleton { background-image: linear-gradient(100deg, rgb(var(--soft)) 30%, rgb(var(--card)) 50%, rgb(var(--soft)) 70%); background-size: 220% 100%; animation: skeleton-sweep 1.5s ease-in-out infinite; }
@keyframes skeleton-sweep { from { background-position: 120% 0; } to { background-position: -120% 0; } }

.tile-hover:active { transform: scale(.992); }

@media (prefers-reduced-motion: reduce) {
  .tile-in, .chart-reveal, .meter > i, .live-dot::after, .skeleton { animation: none !important; }
  .meter > i { transition: none; }
}

/* every other grid of tiles (server page, admin, status ...) enters with a short cascade too */
main .grid > .tile:not(.tile-in),
main .grid > .panel:not(.tile-in) { animation: tile-in .5s cubic-bezier(.2, .8, .2, 1) both; }
main .grid > :nth-child(2) { animation-delay: 50ms; }
main .grid > :nth-child(3) { animation-delay: 100ms; }
main .grid > :nth-child(4) { animation-delay: 150ms; }
main .grid > :nth-child(5) { animation-delay: 200ms; }
main .grid > :nth-child(6) { animation-delay: 250ms; }
main .grid > :nth-child(n+7) { animation-delay: 300ms; }
@media (prefers-reduced-motion: reduce) {
  main .grid > .tile, main .grid > .panel { animation: none !important; }
}

/* =====================================================================================================
   Visual language pass: buttons, magnetic CTAs, split button, switches, copy burst, view transitions,
   hero depth, status breathing, roll digits, skeleton swap, micro-interactions, density.
   Everything moving is switched off for prefers-reduced-motion (see the block at the end of the file).
   ===================================================================================================== */

/* the page colour also paints the canvas, so a view-transition slide never shows a white edge */
html { background-color: rgb(var(--page)); }

/* animated glyphs inside buttons: styles/buttons.css */

/* copy -> check with a small burst */
.copy-ico { position: relative; display: inline-grid; width: 16px; height: 16px; place-items: center; flex-shrink: 0; }
.copy-ico > .ico-copy, .copy-ico > .ico-check { grid-area: 1 / 1; transition: transform .28s cubic-bezier(.34, 1.56, .64, 1), opacity .18s ease; }
.copy-ico > .ico-check { transform: scale(0) rotate(-40deg); opacity: 0; color: rgb(var(--ok)); }
.copy-ico[data-done='true'] > .ico-copy { transform: scale(0) rotate(40deg); opacity: 0; }
.copy-ico[data-done='true'] > .ico-check { transform: none; opacity: 1; }
.ico-check path { stroke-dasharray: 24; stroke-dashoffset: 24; }
.copy-ico[data-done='true'] .ico-check path { animation: check-draw .32s ease-out .05s forwards; }
@keyframes check-draw { to { stroke-dashoffset: 0; } }

.burst { position: absolute; left: 50%; top: 50%; width: 0; height: 0; pointer-events: none; }
.burst i {
  position: absolute; left: -2.5px; top: -2.5px; width: 5px; height: 5px; border-radius: 9999px;
  background: rgb(var(--ok)); opacity: 0;
  animation: burst .9s cubic-bezier(.15, .7, .3, 1) forwards;
}
.burst i:nth-child(3n+1) { background: rgb(var(--brand)); width: 4px; height: 4px; }
.burst i:nth-child(3n+2) { background: #f0b232; }
.burst i:nth-child(4n) { background: #ec4899; height: 4px; }
@keyframes burst {
  0% { opacity: 1; transform: rotate(var(--a)) translateY(-3px) scale(.4); }
  25% { opacity: 1; }
  100% { opacity: 0; transform: rotate(var(--a)) translateY(calc(var(--r, 17px) * -1)) scale(.9); }
}

/* ---------- iOS-style switch (input type=checkbox role=switch) ---------- */
@layer components {
  .switch {
    -webkit-appearance: none; appearance: none; position: relative; flex-shrink: 0; display: inline-block; vertical-align: middle;
    width: 2.75rem; height: 1.625rem; border-radius: 9999px; cursor: pointer; margin: 0;
    background-color: rgb(var(--field));
    transition: background-color .25s ease, box-shadow .25s ease;
  }
  .switch::before {
    content: ''; position: absolute; left: 3px; top: 3px; width: 20px; height: 20px; border-radius: 9999px; background: #fff;
    box-shadow: 0 1px 3px rgb(0 0 0 / 0.35), 0 0 0 .5px rgb(0 0 0 / 0.08);
    transition: transform .42s cubic-bezier(.34, 1.56, .64, 1), width .18s ease;
  }
  .switch:checked { background-image: linear-gradient(135deg, rgb(var(--brand)), rgb(var(--brand-2))); box-shadow: 0 4px 12px -4px rgb(var(--brand) / 0.55); }
  .switch:checked::before { transform: translateX(18px); }
  .switch:active:not(:disabled)::before { width: 25px; }
  .switch:checked:active:not(:disabled)::before { transform: translateX(13px); }
  .switch:disabled { opacity: .5; cursor: not-allowed; }
}

/* ---------- checkbox whose tick is drawn ---------- */
@layer base {
  input[type='checkbox']:not(.switch) {
    -webkit-appearance: none; appearance: none; position: relative; flex-shrink: 0; display: inline-block; vertical-align: middle;
    width: 1.125rem; height: 1.125rem; margin: 0; cursor: pointer;
    border-radius: 6px; border: 2px solid rgb(var(--field)); background-color: rgb(var(--card));
    transition: background-color .18s ease, border-color .18s ease, transform .18s cubic-bezier(.34, 1.56, .64, 1);
  }
  input[type='checkbox']:not(.switch):active:not(:disabled) { transform: scale(.88); }
  input[type='checkbox']:not(.switch):checked {
    border-color: transparent;
    background-image: linear-gradient(135deg, rgb(var(--brand)), rgb(var(--brand-2)));
  }
  input[type='checkbox']:not(.switch)::after {
    content: ''; position: absolute; left: 29%; top: 9%; width: 30%; height: 56%;
    border: solid #fff; border-width: 0 2.5px 2.5px 0; transform: rotate(45deg); opacity: 0;
  }
  input[type='checkbox']:not(.switch):checked::after { opacity: 1; animation: tick-draw .3s ease-out both; }
  input[type='checkbox']:not(.switch):disabled { opacity: .5; cursor: not-allowed; }
}
@keyframes tick-draw {
  0% { clip-path: inset(100% 100% 0 0); }
  45% { clip-path: inset(72% 0 0 0); }
  100% { clip-path: inset(0 0 0 0); }
}

/* ---------- tabs / segmented controls: the active pill slides (positions come from installSegIndicator()) ---------- */
.seg[data-ind]::before {
  content: ''; position: absolute; left: 0; top: 0; z-index: 0; pointer-events: none;
  width: var(--ind-w); height: var(--ind-h); transform: translate(var(--ind-x), var(--ind-y));
  border-radius: 9999px; background: rgb(var(--seg-on));
  box-shadow: var(--shadow-1);
}
.seg[data-ind-anim]::before { transition: transform .38s cubic-bezier(.34, 1.3, .5, 1), width .3s cubic-bezier(.2, .8, .2, 1), height .2s ease; }
.seg[data-ind] > .seg-item[aria-pressed='true'], .seg[data-ind] > .seg-item[aria-current='page'], .seg[data-ind] > .seg-item.on { background: transparent; box-shadow: none; }

/* ---------- favourite star ---------- */
.star-pop { display: inline-block; animation: star-pop .55s cubic-bezier(.3, 1.7, .5, 1) both; }
@keyframes star-pop {
  0% { transform: scale(.4) rotate(-50deg); }
  55% { transform: scale(1.5) rotate(14deg); }
  100% { transform: scale(1) rotate(0); }
}
.star-wrap { position: relative; display: inline-grid; place-items: center; }

/* ---------- toasts spring in and out ---------- */
.toast-in { animation: toast-in .46s cubic-bezier(.34, 1.56, .64, 1) both; }
.toast-out { animation: toast-out .2s ease-in both; }
@keyframes toast-in { from { opacity: 0; transform: translateY(16px) scale(.9); } to { opacity: 1; transform: none; } }
@keyframes toast-out { to { opacity: 0; transform: translateY(8px) scale(.94); } }

/* ---------- view transitions: route change and theme reveal ---------- */
/* the glass header and bottom bar must NOT be separate transition layers: a translucent backdrop-filter element is captured against black */
body header.glass, body nav.glass.fixed { view-transition-name: none; }
@keyframes vt-out { to { opacity: 0; transform: translateY(-5px); } }
@keyframes vt-in { from { opacity: 0; transform: translateY(9px); } }
::view-transition-old(root) { animation: vt-out .16s ease-in both; }
::view-transition-new(root) { animation: vt-in .3s cubic-bezier(.2, .8, .2, 1) both; }
/* the avatar morph: tile -> page banner */
::view-transition-group(*) { animation-duration: .42s; animation-timing-function: cubic-bezier(.2, .8, .2, 1); }
::view-transition-group(app-header), ::view-transition-group(app-nav) { animation: none; }
::view-transition-old(app-header), ::view-transition-new(app-header), ::view-transition-old(app-nav), ::view-transition-new(app-nav) { animation: none; }
.vt-theme::view-transition-old(root), .vt-theme::view-transition-new(root) { animation: none; mix-blend-mode: normal; }
.vt-theme::view-transition-old(root) { z-index: 1; }
.vt-theme::view-transition-new(root) { z-index: 2; }

/* ---------- hero depth: layers drift with the pointer, a soft highlight follows it, a thin light runs along the edge ---------- */
@property --edge-a { syntax: '<angle>'; inherits: false; initial-value: 0deg; }
@media (hover: hover) and (pointer: fine) {
  .depth { --px: 0; --py: 0; --ho: 0; --hx: 50%; --hy: 30%; }
  .depth::before {
    content: ''; position: absolute; inset: 0; border-radius: inherit; pointer-events: none;
    opacity: var(--ho); transition: opacity .35s ease;
    background: radial-gradient(420px circle at var(--hx) var(--hy), rgb(255 255 255 / 0.24), transparent 62%);
  }
  .depth-l1 { translate: calc(var(--px, 0) * 4px) calc(var(--py, 0) * 4px); transition: translate .3s ease-out; }
  .depth-l2 { translate: calc(var(--px, 0) * -4px) calc(var(--py, 0) * -4px); transition: translate .3s ease-out; }
  .depth::after {
    content: ''; position: absolute; inset: 0; border-radius: inherit; padding: 1px; pointer-events: none;
    background: conic-gradient(from var(--edge-a), transparent 0deg, transparent 236deg, rgb(255 255 255 / 0.85) 300deg, transparent 346deg);
    -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
    -webkit-mask-composite: xor; mask-composite: exclude;
    animation: edge-spin 8s linear infinite;
  }
}
@keyframes edge-spin { to { --edge-a: 360deg; } }

/* ---------- status that breathes ---------- */
.pill-ok.live { animation: breathe-ok 3.4s ease-in-out infinite; }
@keyframes breathe-ok {
  0%, 100% { box-shadow: 0 0 0 0 rgb(var(--ok) / 0); }
  50% { box-shadow: 0 0 0 3px rgb(var(--ok) / 0.13), 0 0 14px rgb(var(--ok) / 0.28); }
}
.pill-warn.lag { animation: glow-warn 5.2s ease-in-out infinite; }
.pill-warn.lag::before { animation: glow-dot 5.2s ease-in-out infinite; }
@keyframes glow-warn {
  0%, 100% { box-shadow: 0 0 0 0 rgb(var(--warn) / 0); }
  50% { box-shadow: 0 0 12px 1px rgb(var(--warn) / 0.32); }
}
@keyframes glow-dot { 0%, 100% { opacity: 1; } 50% { opacity: .45; } }
/* a server just went offline: one red ring over the tile */
.flash-ring {
  position: absolute; inset: 0; border-radius: inherit; pointer-events: none; z-index: 5;
  animation: flash-ring 1.9s ease-out both;
}
@keyframes flash-ring {
  0% { box-shadow: inset 0 0 0 0 rgb(var(--bad) / 0), 0 0 0 0 rgb(var(--bad) / 0); }
  14% { box-shadow: inset 0 0 0 4px rgb(var(--bad) / 0.9), 0 0 0 4px rgb(var(--bad) / 0.55), 0 0 34px 4px rgb(var(--bad) / 0.5); }
  55% { box-shadow: inset 0 0 0 3px rgb(var(--bad) / 0.5), 0 0 0 3px rgb(var(--bad) / 0.3), 0 0 22px 2px rgb(var(--bad) / 0.25); }
  100% { box-shadow: inset 0 0 0 0 rgb(var(--bad) / 0), 0 0 0 0 rgb(var(--bad) / 0); }
}

/* ---------- flip-board numbers ---------- */
.roll { display: inline-block; position: relative; white-space: nowrap; font-variant-numeric: tabular-nums; }
/* the invisible in-flow digit (.roll-g) gives the box its width and keeps the text baseline right (overflow: clip keeps it);
   the column of 0..9 is absolute and slides under the clip */
.roll-d { display: inline-block; position: relative; line-height: 1; overflow: hidden; overflow: clip; user-select: none; }
.roll-g { visibility: hidden; }
.roll-col { position: absolute; left: 0; top: 0; display: block; transition: transform .75s cubic-bezier(.2, .85, .2, 1); }
.roll-col > span { display: block; height: 1em; line-height: 1; }
.roll-d.new { animation: roll-in .45s ease-out both; }
@keyframes roll-in { from { opacity: 0; transform: translateY(.35em); } }
.delta-chip {
  position: absolute; right: 0; bottom: 100%; margin-bottom: 2px; z-index: 6; pointer-events: none;
  font-size: 12px; line-height: 1; font-weight: 800; letter-spacing: 0; padding: 3px 7px; border-radius: 9999px; white-space: nowrap;
  animation: delta-chip 2.1s ease-out both;
}
.delta-chip.up { background: rgb(var(--okbg)); color: rgb(var(--ok)); }
.delta-chip.down { background: rgb(var(--badbg)); color: rgb(var(--bad)); }
@keyframes delta-chip {
  0% { opacity: 0; transform: translateY(7px) scale(.8); }
  12% { opacity: 1; transform: none; }
  78% { opacity: 1; transform: none; }
  100% { opacity: 0; transform: translateY(-7px); }
}

/* ---------- skeletons: same shapes as the content; content fades in when it arrives ---------- */
.fade-in { animation: fade-in .4s ease-out both; }
@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
.skel-line { height: 12px; border-radius: 9999px; }

/* ---------- empty-state illustrations ---------- */
.art-float { animation: art-float 4.5s ease-in-out infinite alternate; transform-box: fill-box; transform-origin: center; }
.art-float-2 { animation: art-float 5.6s ease-in-out -2s infinite alternate; transform-box: fill-box; transform-origin: center; }
.art-twinkle { animation: art-twinkle 2.6s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
.art-blink { animation: art-blink 2.4s ease-in-out infinite; }
.art-wobble { animation: art-wobble 3.6s ease-in-out infinite; transform-box: fill-box; transform-origin: 50% 100%; }
.art-spin { animation: spin 14s linear infinite; transform-box: fill-box; transform-origin: center; }
@keyframes art-float { from { transform: translateY(-3px); } to { transform: translateY(4px); } }
@keyframes art-twinkle { 0%, 100% { opacity: .35; transform: scale(.7); } 50% { opacity: .9; transform: scale(1.15) rotate(12deg); } }
@keyframes art-blink { 0%, 100% { opacity: 1; } 45% { opacity: .25; } }
@keyframes art-wobble { 0%, 100% { transform: rotate(-3deg); } 50% { transform: rotate(3deg); } }

/* ---------- density: Обычная / Компактная (html[data-density='compact']) ---------- */
:root[data-density='compact'] body { font-size: 14px; }
:root[data-density='compact'] .p-5 { padding: .9rem; }
:root[data-density='compact'] .p-6 { padding: 1rem; }
:root[data-density='compact'] .p-4 { padding: .75rem; }
:root[data-density='compact'] .p-\[18px\] { padding: .8rem; }
:root[data-density='compact'] .px-5 { padding-left: .9rem; padding-right: .9rem; }
:root[data-density='compact'] .px-6 { padding-left: 1.1rem; padding-right: 1.1rem; }
:root[data-density='compact'] .py-4 { padding-top: .7rem; padding-bottom: .7rem; }
:root[data-density='compact'] .py-10 { padding-top: 1.5rem; padding-bottom: 1.5rem; }
:root[data-density='compact'] .gap-3\.5 { gap: .6rem; }
:root[data-density='compact'] .gap-5 { gap: .9rem; }
:root[data-density='compact'] .gap-6 { gap: 1rem; }
:root[data-density='compact'] .space-y-5 > :not([hidden]) ~ :not([hidden]) { margin-top: .85rem; }
:root[data-density='compact'] .space-y-4 > :not([hidden]) ~ :not([hidden]) { margin-top: .7rem; }
:root[data-density='compact'] .space-y-3\.5 > :not([hidden]) ~ :not([hidden]) { margin-top: .6rem; }
:root[data-density='compact'] .space-y-3 > :not([hidden]) ~ :not([hidden]) { margin-top: .5rem; }
:root[data-density='compact'] .space-y-2\.5 > :not([hidden]) ~ :not([hidden]) { margin-top: .4rem; }
:root[data-density='compact'] .tile, :root[data-density='compact'] .panel { border-radius: 20px; }
:root[data-density='compact'] .stat-v { font-size: 28px; }
:root[data-density='compact'] .input { padding-top: .35rem; padding-bottom: .35rem; }
:root[data-density='compact'] .seg-item { padding: .3rem .8rem; }
:root[data-density='compact'] .pill { padding-top: .05rem; padding-bottom: .05rem; }
:root[data-density='compact'] .h-\[88px\] { height: 64px; }
:root[data-density='compact'] .text-\[64px\] { font-size: 48px; }
:root[data-density='compact'] .text-\[30px\] { font-size: 24px; }
@media (min-width: 640px) {
  :root[data-density='compact'] .sm\:p-6 { padding: 1rem; }
  :root[data-density='compact'] .sm\:p-\[18px\] { padding: .8rem; }
  :root[data-density='compact'] .stat-v { font-size: 32px; }
  :root[data-density='compact'] .sm\:text-\[78px\] { font-size: 60px; }
}
@media (min-width: 1024px) {
  :root[data-density='compact'] .lg\:p-6 { padding: 1rem; }
}

/* ---------- 404 ---------- */
.nf-code { background: linear-gradient(135deg, rgb(var(--brand)), rgb(var(--brand-2))); -webkit-background-clip: text; background-clip: text; color: transparent; }

/* ---------- reduced motion: nothing moves, state changes are instant ---------- */
@media (prefers-reduced-motion: reduce) {
  .depth::before, .depth::after { display: none !important; }
  [data-magnetic] { translate: none !important; }
  .depth-l1, .depth-l2 { translate: none !important; }
  .roll-col, .switch::before, .seg[data-ind]::before, .split-menu, .star-pop, .toast-in, .toast-out, .delta-chip, .flash-ring,
  .burst i, .art-float, .art-float-2, .art-twinkle, .art-blink, .art-wobble, .art-spin, .fade-in, .pill-ok.live, .pill-warn.lag, .pill-warn.lag::before,
  .ico-refresh, .ico-nudge, .ico-share, input[type='checkbox']:not(.switch)::after {
    animation: none !important; transition: none !important;
  }
  .burst { display: none; }
  ::view-transition-group(*), ::view-transition-old(*), ::view-transition-new(*) { animation: none !important; }
}

/* ---------- updates tab ---------- */
.update-hero { background: linear-gradient(135deg, #f59e0b 0%, #ea580c 55%, #be185d 120%); box-shadow: 0 1px 2px rgba(20, 24, 40, .06), 0 22px 44px -18px rgba(234, 88, 12, .55); }
.update-hero-run { background: linear-gradient(135deg, rgb(var(--brand)), rgb(var(--brand-2, var(--brand)))); box-shadow: 0 1px 2px rgba(20, 24, 40, .06), 0 22px 44px -18px rgb(var(--brand) / .55); }
.update-bob { animation: update-bob 1.6s ease-in-out infinite; }
@keyframes update-bob { 0%, 100% { transform: translateY(2px); } 50% { transform: translateY(-3px); } }
.update-progress { height: 8px; border-radius: 9999px; background: rgb(255 255 255 / .25); overflow: hidden; }
.update-progress > i { display: block; height: 100%; width: 38%; border-radius: inherit; background: #fff; animation: update-slide 1.3s ease-in-out infinite; }
@keyframes update-slide { from { transform: translateX(-110%); } to { transform: translateX(290%); } }
@media (prefers-reduced-motion: reduce) { .update-bob, .update-progress > i { animation: none; } .update-progress > i { width: 100%; } }

/* status capsule on covers and gradients */
.pill-glass { display: inline-flex; align-items: center; gap: 7px; padding: 4px 11px 4px 9px; border-radius: 9999px; font-size: 12.5px; font-weight: 800; line-height: 1.2; color: #fff; background: rgb(12 14 26 / .46); -webkit-backdrop-filter: blur(10px) saturate(1.3); backdrop-filter: blur(10px) saturate(1.3); box-shadow: inset 0 0 0 1px rgb(255 255 255 / .22); white-space: nowrap; }
.pill-glass::before { content: ''; width: 8px; height: 8px; border-radius: 9999px; background: var(--dot); box-shadow: 0 0 0 3px color-mix(in srgb, var(--dot) 30%, transparent); }
.pill-glass-ok { --dot: #4ade80; }
.pill-glass-lag { --dot: #fbbf24; }
.pill-glass-bad { --dot: #f87171; }
.pill-glass-mute { --dot: #cbd5e1; }
.pill-glass-ok::before { animation: glass-dot 2.2s ease-in-out infinite; }
@keyframes glass-dot { 0%, 100% { box-shadow: 0 0 0 3px color-mix(in srgb, var(--dot) 28%, transparent); } 50% { box-shadow: 0 0 0 6px color-mix(in srgb, var(--dot) 8%, transparent); } }
@media (prefers-reduced-motion: reduce) { .pill-glass-ok::before { animation: none; } }

/* update marker: a pulsing amber dot */
.update-dot { position: relative; display: inline-block; width: 10px; height: 10px; border-radius: 9999px; background: #f59e0b; box-shadow: 0 0 0 2px rgb(255 255 255 / .85); flex: none; }
.update-dot::after { content: ''; position: absolute; inset: 0; border-radius: inherit; background: #f59e0b; animation: live-ping 1.8s cubic-bezier(0, 0, .2, 1) infinite; }
:root[data-theme='dark'] .update-dot { box-shadow: 0 0 0 2px rgb(var(--card)); }
@media (prefers-reduced-motion: reduce) { .update-dot::after { animation: none; } }
/* ghost buttons on the update hero: light glass instead of dark */
.update-hero .btn-ghost-on-grad { background: rgb(255 255 255 / .2); box-shadow: inset 0 0 0 1px rgb(255 255 255 / .38); }
.update-hero .btn-ghost-on-grad:hover { background: rgb(255 255 255 / .3); }

/* compact icon actions in admin rows: .row-act, styles/buttons.css */

/* ---------- server page: banner, tabs, players, events ---------- */
.chip-glass { display: inline-flex; align-items: center; gap: 6px; border-radius: 9999px; padding: 4px 11px; font-size: 13px; font-weight: 800; color: #fff; background: rgba(8, 10, 20, 0.34); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.16); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); max-width: 100%; }
/* glass / cta buttons: styles/buttons.css */

/* status glow around the banner: green online, amber lag, red offline; it follows the theme's status colours */
.srv-glow { --g: var(--ok); box-shadow: 0 1px 2px rgba(20, 24, 40, 0.08), 0 0 0 1px rgb(var(--g) / 0.5), 0 16px 46px -14px rgb(var(--g) / 0.6); }
.srv-warn { --g: var(--warn); }
.srv-bad { --g: var(--bad); }
.srv-mute { --g: var(--mute); box-shadow: 0 1px 2px rgba(20, 24, 40, 0.08), 0 0 0 1px rgb(var(--g) / 0.3), 0 16px 40px -18px rgb(var(--g) / 0.4); }
.srv-ok { animation: srv-breathe 4.6s ease-in-out infinite; }
@keyframes srv-breathe {
  0%, 100% { box-shadow: 0 1px 2px rgba(20, 24, 40, 0.08), 0 0 0 1px rgb(var(--g) / 0.4), 0 14px 40px -14px rgb(var(--g) / 0.45); }
  50% { box-shadow: 0 1px 2px rgba(20, 24, 40, 0.08), 0 0 0 2px rgb(var(--g) / 0.6), 0 18px 56px -10px rgb(var(--g) / 0.7); }
}
@media (prefers-reduced-motion: reduce) { .srv-ok { animation: none; } }

.srv-tabbar { transition: background-color .2s ease, box-shadow .2s ease; }
.srv-tabbar.is-stuck { background: rgb(var(--page) / 0.78); -webkit-backdrop-filter: blur(14px) saturate(1.3); backdrop-filter: blur(14px) saturate(1.3); box-shadow: 0 1px 0 rgb(var(--line)); }
.no-scrollbar { scrollbar-width: none; }
.no-scrollbar::-webkit-scrollbar { display: none; }
.tab-count { margin-left: 6px; border-radius: 9999px; padding: 0 6px; font-size: 12px; font-weight: 800; background: rgb(var(--ink) / 0.08); font-variant-numeric: tabular-nums; }

.meter.m-ok > i { background: rgb(var(--ok)); }
.meter.m-warn > i { background: rgb(var(--warn)); }
.meter.m-bad > i { background: rgb(var(--bad)); }

.avatar-hue { background: hsl(var(--h) 72% 88%); color: hsl(var(--h) 62% 24%); }
:root[data-theme='dark'] .avatar-hue { background: hsl(var(--h) 42% 26%); color: hsl(var(--h) 90% 86%); }
@media (prefers-color-scheme: dark) { :root:not([data-theme='light']) .avatar-hue { background: hsl(var(--h) 42% 26%); color: hsl(var(--h) 90% 86%); } }

.player-new { animation: player-new 2.6s ease-out both; }
@keyframes player-new {
  0% { background-color: rgb(var(--ok) / 0.28); box-shadow: 0 0 0 4px rgb(var(--ok) / 0.28); }
  100% { background-color: rgb(var(--ok) / 0); box-shadow: 0 0 0 4px rgb(var(--ok) / 0); }
}
@media (prefers-reduced-motion: reduce) { .player-new { animation: none; background-color: rgb(var(--ok) / 0.14); } }

.chip-filter { display: inline-flex; align-items: center; border-radius: 9999px; padding: 6px 14px; font-size: 14px; font-weight: 800; color: rgb(var(--mute)); background: rgb(var(--soft)); transition: color .15s ease, background .15s ease; }
.chip-filter:hover { color: rgb(var(--ink)); }
.chip-filter.on { color: rgb(var(--ink)); background: rgb(var(--seg-on)); box-shadow: 0 0 0 1px rgb(var(--line)), 0 2px 6px rgba(40, 50, 110, 0.1); }
@media (max-width: 639px) { .chip-filter { min-height: 44px; } }

/* determinate update progress: the fill width is --p, no sliding */
.update-progress.det > i { animation: none; transform: none; width: var(--p, 0%); min-width: 6px; transition: width .6s cubic-bezier(.2, .8, .2, 1); }
@media (prefers-reduced-motion: reduce) { .update-progress.det > i { transition: none; } }

/* hint strip under page titles */
.hint-strip { display: flex; align-items: flex-start; gap: 10px; border-radius: var(--r-lg); padding: 10px 14px; font-size: 14px; font-weight: 600; line-height: 1.5; color: rgb(var(--ink)); background: rgb(var(--brand) / .07); box-shadow: inset 0 0 0 1px rgb(var(--brand) / .15); }
.hint-ico { display: inline-grid; place-items: center; flex: none; width: 20px; height: 20px; margin-top: 1px; border-radius: 9999px; font-size: 12px; font-weight: 900; font-style: italic; font-family: Georgia, serif; color: rgb(var(--link)); background: rgb(var(--brand) / .16); }
.hint-more { display: inline; font-weight: 800; color: rgb(var(--link)); border-radius: var(--r-sm); text-decoration: underline; text-underline-offset: 3px; padding: 0 2px; }
.hint-more:hover { text-decoration-thickness: 2px; }
.hint-help { margin-top: 8px; padding-top: 8px; border-top: 1px solid rgb(var(--brand) / .18); color: rgb(var(--mute)); }
.hint-help p + p { margin-top: 6px; }
.hint-help ol, .hint-help ul { margin: 4px 0 0 1.1rem; list-style: decimal; }
.hint-help ul { list-style: disc; }

/* admin sidebar groups */
.adm-group-title { padding: 10px 14px 4px; font-size: 11px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: rgb(var(--mute)); }

/* ---------- black-square safeguard (Chrome) ----------
   Elements with backdrop-filter inside content that animates opacity/transform (every route change re-mounts <main>
   with an entrance animation, tiles cascade in) can flash as a black rectangle on some GPUs. The blur is cosmetic,
   so it is dropped everywhere except full-screen modal overlays; translucent backgrounds are made a bit denser instead. */
.glass {
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  background-image: linear-gradient(rgb(var(--card) / 0.55), rgb(var(--card) / 0.55));
}
.pill-glass { -webkit-backdrop-filter: none; backdrop-filter: none; background: rgb(12 14 26 / 0.6); }
.chip-glass { -webkit-backdrop-filter: none; backdrop-filter: none; background: rgba(8, 10, 20, 0.5); }
.srv-tabbar.is-stuck { -webkit-backdrop-filter: none; backdrop-filter: none; background: rgb(var(--page) / 0.96); }
.auth-card { -webkit-backdrop-filter: none; backdrop-filter: none; }
/* the page entrance is a plain fade: no transform on the big container that holds the whole page */
@keyframes pop-fade { from { opacity: 0; } to { opacity: 1; } }
.pop { animation: pop-fade 0.18s ease-out both; }

/* ---------- no per-frame repaints of big layers (black-square fix, round 2) ----------
   The rotating masked edge light (.depth::after) and the breathing big box-shadow (.srv-ok) re-rasterise large areas
   every frame; when the tab is re-shown or a screenshot is taken Chrome could present such a layer as black. Both are
   static now; the small decorative animations stay but are paused while the page is hidden (see main.tsx). */
.depth::after { animation: none !important; display: none; }
.srv-ok { animation: none !important; box-shadow: 0 1px 2px rgba(20, 24, 40, 0.08), 0 0 0 1px rgb(var(--g) / 0.4), 0 14px 40px -14px rgb(var(--g) / 0.45); }
.pill-ok.live, .pill-warn.lag { animation: none !important; }
html[data-hidden] *, html[data-hidden] *::before, html[data-hidden] *::after { animation-play-state: paused !important; }

/* ---------- news editor: preview parts, flash on focus, drop zones ---------- */
.pv-part { cursor: pointer; border-radius: 4px; outline: 2px solid transparent; outline-offset: 2px; }
.pv-part:hover, .pv-part:focus-visible { outline: 2px dashed rgba(88, 101, 242, 0.85); }
.pv-bad, .pv-bad.pv-part { outline: 2px solid #f23f42; outline-offset: 2px; border-radius: 4px; }
@keyframes flash-ctl { 0% { box-shadow: 0 0 0 0 rgb(var(--brand) / 0.7); } 40% { box-shadow: 0 0 0 5px rgb(var(--brand) / 0.45); } 100% { box-shadow: 0 0 0 0 rgb(var(--brand) / 0); } }
.flash-ctl { animation: flash-ctl 0.7s ease-out 2; border-radius: 16px; }
@media (prefers-reduced-motion: reduce) { .flash-ctl { animation: none; box-shadow: 0 0 0 3px rgb(var(--brand) / 0.6); } }

/* ---------- bisect switches for the black-square hunt: open the panel as /?flat=anim, /?flat=shadow, /?flat=filter or /?flat=all ---------- */
html[data-flat='anim'] *, html[data-flat='anim'] *::before, html[data-flat='anim'] *::after,
html[data-flat='all'] *, html[data-flat='all'] *::before, html[data-flat='all'] *::after { animation: none !important; transition: none !important; }
html[data-flat='shadow'] *, html[data-flat='shadow'] *::before, html[data-flat='shadow'] *::after,
html[data-flat='all'] *, html[data-flat='all'] *::before, html[data-flat='all'] *::after { box-shadow: none !important; text-shadow: none !important; }
html[data-flat='filter'] *, html[data-flat='filter'] *::before, html[data-flat='filter'] *::after,
html[data-flat='all'] *, html[data-flat='all'] *::before, html[data-flat='all'] *::after { filter: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; mask: none !important; -webkit-mask: none !important; clip-path: none !important; }

/* ---------- black-square fix, round 3 (the square is gone with animations off, so it is a compositor layer) ----------
   - entrance animations used fill-mode "both": a finished animation with a forwards fill keeps its element on its own
     compositor layer for good (every tile, every chart); "backwards" only applies the start state during the delay.
   - decorative endless loops (pings, rings, floats, glows) each keep a layer alive; they are static now. Spinners,
     skeletons and the update progress stay. */
.tile-in, .pop, .fade-in, .chart-reveal, .roll-d.new { animation-fill-mode: backwards; }
.pill.live::before, .live-dot::after, .update-dot::after, .pill-glass-ok::before, .update-bob,
.art-float, .art-float-2, .art-twinkle, .art-blink, .art-wobble, .art-spin, .auth-glow, .auth-float { animation: none !important; }

/* finer bisect switches: /?flat=enter (entrance animations), /?flat=trans (transitions), /?flat=loop (endless loops) */
html[data-flat='enter'] .tile-in, html[data-flat='enter'] .pop, html[data-flat='enter'] .fade-in, html[data-flat='enter'] .chart-reveal,
html[data-flat='enter'] .roll-d.new, html[data-flat='enter'] .toast-in { animation: none !important; }
html[data-flat='trans'] *, html[data-flat='trans'] *::before, html[data-flat='trans'] *::after { transition: none !important; }

/* ---------- black-square fix, round 4 ----------
   Only transitions made it appear. When the window is re-shown (tab switch, PrintScreen, Chrome's occlusion tracking)
   the browser re-applies :hover under the cursor, and the server card under it ran a transform/translate transition:
   a big rounded overflow-hidden card was promoted to a compositor layer for a moment and could be drawn black.
   Cards now change only their shadow on hover (no transform), and the pointer parallax layers are static. */
.tile-hover { transition: box-shadow .18s ease; }
.tile-hover:hover, .tile-hover:active { transform: none; }
.depth-l1, .depth-l2 { translate: none !important; transition: none !important; }
.depth::before { display: none; }

/* bisect by transitioned property: /?flat=tx (no transform), to (no opacity), tc (no colours), ts (no shadow/filter), tw (no size/layout) */
html[data-flat='tx'] *, html[data-flat='tx'] *::before, html[data-flat='tx'] *::after {
  transition-property: color, background-color, border-color, outline-color, fill, stroke, text-decoration-color, opacity, box-shadow, filter, backdrop-filter, width, height, left, top, margin, padding, max-height, grid-template-rows, stroke-dashoffset, background-position, clip-path !important;
}
html[data-flat='to'] *, html[data-flat='to'] *::before, html[data-flat='to'] *::after {
  transition-property: color, background-color, border-color, outline-color, fill, stroke, text-decoration-color, box-shadow, filter, backdrop-filter, width, height, transform, translate, scale, rotate, left, top, margin, padding, max-height, grid-template-rows, stroke-dashoffset, background-position, clip-path !important;
}
html[data-flat='tc'] *, html[data-flat='tc'] *::before, html[data-flat='tc'] *::after {
  transition-property: opacity, box-shadow, filter, backdrop-filter, width, height, transform, translate, scale, rotate, left, top, margin, padding, max-height, grid-template-rows, stroke-dashoffset, background-position, clip-path !important;
}
html[data-flat='ts'] *, html[data-flat='ts'] *::before, html[data-flat='ts'] *::after {
  transition-property: color, background-color, border-color, outline-color, fill, stroke, text-decoration-color, opacity, width, height, transform, translate, scale, rotate, left, top, margin, padding, max-height, grid-template-rows, stroke-dashoffset, background-position, clip-path !important;
}
html[data-flat='tw'] *, html[data-flat='tw'] *::before, html[data-flat='tw'] *::after {
  transition-property: color, background-color, border-color, outline-color, fill, stroke, text-decoration-color, opacity, box-shadow, filter, backdrop-filter, transform, translate, scale, rotate !important;
}

/* which colour property: /?flat=cb (only background-color transitions on), cc (color), cd (border/outline), cf (fill/stroke); the rest of the colour transitions are off */
html[data-flat='cb'] *, html[data-flat='cb'] *::before, html[data-flat='cb'] *::after { transition-property: opacity, box-shadow, filter, backdrop-filter, width, height, transform, translate, scale, rotate, left, top, margin, padding, max-height, grid-template-rows, stroke-dashoffset, background-position, clip-path, background-color !important; }
html[data-flat='cc'] *, html[data-flat='cc'] *::before, html[data-flat='cc'] *::after { transition-property: opacity, box-shadow, filter, backdrop-filter, width, height, transform, translate, scale, rotate, left, top, margin, padding, max-height, grid-template-rows, stroke-dashoffset, background-position, clip-path, color !important; }
html[data-flat='cd'] *, html[data-flat='cd'] *::before, html[data-flat='cd'] *::after { transition-property: opacity, box-shadow, filter, backdrop-filter, width, height, transform, translate, scale, rotate, left, top, margin, padding, max-height, grid-template-rows, stroke-dashoffset, background-position, clip-path, border-color, outline-color !important; }
html[data-flat='cf'] *, html[data-flat='cf'] *::before, html[data-flat='cf'] *::after { transition-property: opacity, box-shadow, filter, backdrop-filter, width, height, transform, translate, scale, rotate, left, top, margin, padding, max-height, grid-template-rows, stroke-dashoffset, background-position, clip-path, fill, stroke, text-decoration-color !important; }

/* ---------- black-square fix, round 5: the focus outline ----------
   Found by bisecting: the square shows only when border/outline-colour transitions run. A key press (PrintScreen) or a
   window re-focus re-applies :focus-visible to the last focused element (often a big container or a card link); its
   outline transitioned from the browser's default (black) focus ring to transparent: a black frame for ~150 ms.
   The focus ring in this UI is a box-shadow ring, so the outline is removed entirely and the colour properties
   no longer transition by default. */
:focus, :focus-visible { outline: 0 !important; }
.transition { transition-property: color, background-color, fill, stroke, opacity, box-shadow, transform, filter !important; }

/* =====================================================================================================
   Quality pass: state views, foldable server sections, admin shortcuts, setup wizard,
   appearance options (less motion / large text / high contrast) and one visible keyboard focus ring.
   ===================================================================================================== */

/* ---------- focus: every interactive element gets a box-shadow ring (outlines are removed above) ----------
   Utilities and component shadows live in cascade layers, so this unlayered rule wins; the ring replaces the element's
   own shadow while it is focused. Containers that receive focus from code (main, dialogs) stay quiet. */
:focus-visible:not(main):not([role='dialog']):not([role='alertdialog']) {
  outline: 0 !important;
  box-shadow: 0 0 0 2px rgb(var(--page)), 0 0 0 4px rgb(var(--link)) !important;
}
/* inside clipping containers (segmented controls, scrolling strips, lists with overflow hidden) the ring is drawn inward */
.seg-item:focus-visible,
.split-item:focus-visible,
.srv-chip:focus-visible,
.adm-pin:focus-visible,
.pl-row:focus-visible,
.chip-filter:focus-visible {
  box-shadow: inset 0 0 0 2px rgb(var(--link)) !important;
}
/* on covers and gradients the ring is white with a dark inner edge */
.btn-glass:focus-visible, .btn-glass-quiet:focus-visible, .btn-icon-glass:focus-visible, .btn-cta:focus-visible, .btn-on-grad:focus-visible,
.btn-ghost-on-grad:focus-visible, .pp-copy:focus-visible, .chip-glass a:focus-visible, .pp-v a:focus-visible {
  box-shadow: 0 0 0 2px rgb(0 0 0 / 0.45), 0 0 0 4px #fff !important;
}
a:focus-visible, button.text-link:focus-visible, .hint-more:focus-visible { border-radius: var(--r-sm); }

/* ---------- state views ---------- */
[data-state='error'].panel { box-shadow: var(--shadow-2), inset 0 0 0 1px rgb(var(--bad) / 0.25); }

/* ---------- server page: foldable sections and the mini table of contents ---------- */
.srv-sec-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 12px; margin-bottom: 12px; }
/* the title takes the free space and wraps whole words; the controls move to the next line when they do not fit */
.srv-sec-head > h2 { flex: 1 1 10rem; }
.srv-sec.is-closed > .srv-sec-head { margin-bottom: 0; }
.srv-sec-bare > .srv-sec-head { margin-bottom: 8px; padding: 0 4px; }
.srv-sec-bare.is-closed > .srv-sec-head { margin-bottom: 0; }
.srv-sec-btn {
  display: flex; align-items: center; gap: 8px; max-width: 100%; min-height: 32px; margin: -4px -8px; padding: 4px 8px;
  border-radius: var(--r-md); text-align: left; font: inherit; color: inherit; transition: background-color .15s ease;
}
.srv-sec-btn:hover { background: rgb(var(--soft)); }
.srv-sec-chev { flex: none; color: rgb(var(--mute)); transition: transform .2s ease; }
.srv-sec.is-closed .srv-sec-chev { transform: rotate(-90deg); }
.srv-sec:focus { outline: 0; }
@media (max-width: 639px) { .srv-sec-btn { min-height: 44px; } }

.srv-chips { display: flex; gap: 6px; overflow-x: auto; margin-top: 6px; padding: 2px 3px 4px; max-width: 100%; }
.srv-chip {
  flex: none; display: inline-flex; align-items: center; min-height: 32px; border-radius: 9999px; padding: 4px 12px;
  font-size: 13px; font-weight: 800; color: rgb(var(--mute)); background: rgb(var(--soft)); transition: color .15s ease, background-color .15s ease;
}
.srv-chip:hover { color: rgb(var(--ink)); }
.srv-chip[aria-current='true'] { color: rgb(var(--ink)); background: rgb(var(--seg-on)); box-shadow: 0 0 0 1px rgb(var(--line)); }
.srv-chip[data-closed='true']::after { content: '+'; margin-left: 5px; font-weight: 900; opacity: .7; }
@media (max-width: 639px) { .srv-chip { min-height: 36px; } }

/* ---------- admin sidebar: pins and recent sections ---------- */
.adm-item { position: relative; display: flex; min-width: 0; flex: none; }
.adm-pin { display: none; }
@media (min-width: 768px) {
  .adm-item { display: block; flex: initial; }
  .adm-pin {
    display: grid; position: absolute; right: 6px; top: 50%; transform: translateY(-50%); place-items: center;
    width: 28px; height: 28px; border-radius: 9999px; font-size: 15px; line-height: 1; color: rgb(var(--mute));
    opacity: 0; transition: opacity .15s ease, color .15s ease, background-color .15s ease;
  }
  .adm-item:hover .adm-pin, .adm-item:focus-within .adm-pin, .adm-item[data-pinned='true'] .adm-pin { opacity: 1; }
  .adm-item[data-pinned='true'] .adm-pin { color: rgb(var(--warn)); }
  .adm-item[data-current='true'] .adm-pin, .adm-item[data-current='true'] .adm-pin:hover { color: #fff; }
  .adm-pin:hover { background: rgb(var(--soft)); }
}
@media (min-width: 768px) and (hover: none) { .adm-pin { opacity: .75; } }
/* phones: the nav is a horizontal strip; only the section you are in shows its star, right after its chip */
@media (max-width: 767px) {
  .adm-item[data-current='true'] .adm-pin {
    display: grid; flex: none; place-items: center; width: 36px; height: 36px; align-self: center; border-radius: 9999px;
    font-size: 17px; color: rgb(var(--mute)); background: rgb(var(--soft));
  }
  .adm-item[data-current='true'][data-pinned='true'] .adm-pin { color: rgb(var(--warn)); }
}

/* ---------- Discord setup wizard ---------- */
.dw-steps { display: grid; gap: 10px; }
.dw-step { display: flex; gap: 12px; border-radius: var(--r-lg); padding: 12px 14px; background: rgb(var(--soft)); }
.dw-step[data-state='current'] { background: rgb(var(--brand) / 0.08); box-shadow: inset 0 0 0 1.5px rgb(var(--brand) / 0.4); }
.dw-step[data-state='blocked'] { color: rgb(var(--mute)); }
.dw-mark {
  display: grid; place-items: center; flex: none; width: 28px; height: 28px; border-radius: 9999px;
  font-size: 14px; font-weight: 900; color: rgb(var(--mute)); background: rgb(var(--card));
}
.dw-step[data-state='done'] .dw-mark { color: rgb(var(--ok)); background: rgb(var(--okbg)); }
.dw-step[data-state='current'] .dw-mark { color: #fff; background: rgb(var(--brand)); }

/* ---------- appearance: «Меньше движения» (html[data-motion='reduce']); the OS setting is handled by the media queries above ---------- */
html[data-motion='reduce'] *, html[data-motion='reduce'] *::before, html[data-motion='reduce'] *::after {
  animation-duration: 0.01ms !important;
  animation-iteration-count: 1 !important;
  animation-delay: 0s !important;
  transition-duration: 0.01ms !important;
  transition-delay: 0s !important;
  scroll-behavior: auto !important;
}
html[data-motion='reduce'] :is(.auth-glow, .auth-float, .skeleton, .tile-in, .chart-reveal, .meter > i, .update-bob, .art-float, .art-float-2, .art-twinkle, .art-blink, .art-wobble, .art-spin, .toast-in, .toast-out, .pop, .fade-in, .showcase-tile, .auth-card, .auth-swap, .flash-ring, .burst i, .delta-chip) {
  animation: none !important;
}
html[data-motion='reduce'] :is(.pill.live, .live-dot, .update-dot, .pill-glass-ok)::before,
html[data-motion='reduce'] :is(.live-dot, .update-dot)::after { animation: none !important; }
html[data-motion='reduce'] main .grid > .tile, html[data-motion='reduce'] main .grid > .panel { animation: none !important; }
html[data-motion='reduce'] .update-progress > i { animation: none !important; width: 100%; }
/* a spinner must still say "busy": keep a slow rotation */
html[data-motion='reduce'] .animate-spin, html[data-motion='reduce'] .ico-refresh.spinning { animation: spin 2s linear infinite !important; }
html[data-motion='reduce'] [data-magnetic], html[data-motion='reduce'] .depth-l1, html[data-motion='reduce'] .depth-l2 { translate: none !important; }
html[data-motion='reduce'] .tile-hover:active { transform: none !important; }
html[data-motion='reduce'] .depth::before, html[data-motion='reduce'] .depth::after { display: none !important; }
html[data-motion='reduce'] ::view-transition-group(*), html[data-motion='reduce'] ::view-transition-old(*), html[data-motion='reduce'] ::view-transition-new(*) { animation: none !important; }

/* ---------- appearance: «Крупный текст» (html[data-text='large']): root 112.5 %, fixed pixel sizes follow ---------- */
html[data-text='large'] { font-size: 112.5%; }
html[data-text='large'] body { font-size: calc(15px * 1.125); }
html[data-text='large'][data-density='compact'] body { font-size: calc(14px * 1.125); }
html[data-text='large'] .text-\[10px\] { font-size: calc(10px * 1.125); }
html[data-text='large'] :is(.text-\[11px\], .adm-group-title, .pp-k) { font-size: calc(11px * 1.125); }
html[data-text='large'] :is(.text-\[12px\], .tab-count, .hc-legend, .split-item small) { font-size: calc(12px * 1.125); }
html[data-text='large'] :is(.text-\[13px\], .pill, .stat-k, .stat-s, .chip-glass, .srv-chip, .pp-v code) { font-size: calc(13px * 1.125); }
html[data-text='large'] :is(.text-\[14px\], .text-\[14\.5px\], .hint-strip, .chip-filter, .pp-v) { font-size: calc(14px * 1.125); }
html[data-text='large'] .text-\[15px\] { font-size: calc(15px * 1.125); }
html[data-text='large'] .stat-v { font-size: calc(34px * 1.125); }
@media (min-width: 640px) { html[data-text='large'] .stat-v { font-size: calc(40px * 1.125); } }

/* ---------- appearance: «Высокий контраст» (html[data-contrast='high']): black ink, firm borders ---------- */
:root[data-contrast='high'] {
  --ink: 0 0 0;
  --mute: 52 58 72;
  --line: 140 146 160;
  --field: 70 76 90;
  --ok: 8 88 44;
  --warn: 104 66 0;
  --bad: 150 18 18;
  --badsolid: 150 18 18;
  --tile-border: rgb(110 116 130);
}
:root[data-theme='dark'][data-contrast='high'] {
  --ink: 255 255 255;
  --mute: 206 211 224;
  --line: 120 126 144;
  --field: 160 166 184;
  --ok: 134 239 172;
  --warn: 253 224 71;
  --bad: 252 165 165;
  --tile-border: rgb(255 255 255 / 0.4);
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light'])[data-contrast='high'] {
    --ink: 255 255 255;
    --mute: 206 211 224;
    --line: 120 126 144;
    --field: 160 166 184;
    --ok: 134 239 172;
    --warn: 253 224 71;
    --bad: 252 165 165;
    --tile-border: rgb(255 255 255 / 0.4);
  }
}
html[data-contrast='high'] .panel, html[data-contrast='high'] .tile { border-width: 2px; }
html[data-contrast='high'] .pill { box-shadow: inset 0 0 0 1px currentColor; }
html[data-contrast='high'] .seg { box-shadow: inset 0 0 0 1px rgb(var(--field)); }
html[data-contrast='high'] .seg-item[aria-pressed='true'], html[data-contrast='high'] .seg-item[aria-current='page'], html[data-contrast='high'] .seg-item.on { box-shadow: inset 0 0 0 2px rgb(var(--ink)); }
html[data-contrast='high'] .hint-strip { box-shadow: inset 0 0 0 1px rgb(var(--field)); }
html[data-contrast='high'] main a:not([class]) { text-decoration-line: underline; text-underline-offset: 3px; }
