export function OrDivider() {
  return (
    <div className="my-4 flex items-center gap-3 text-sm font-bold text-mute" aria-hidden>
      <span className="h-px flex-1 bg-line" />
      {t('auth.or')}
      <span className="h-px flex-1 bg-line" />
