  if (!a || !a.hasAttribute('href') || a.hasAttribute('download') || (a.target && a.target !== '_self')) return;
  const href = a.getAttribute('href') ?? '';
  if (href.startsWith('#') && !href.startsWith('#/')) return; // an anchor on the page
